#if ZKN_POSEIDON_BLS12381_ARITIES
static const uint32_t POSEIDON_BLS12381_MODULUS[8] = {
    0x00000001u, 0xffffffffu, 0xfffe5bfeu, 0x53bda402u, 0x09a1d805u, 0x3339d808u, 0x299d7d48u, 0x73eda753u
};
#endif

const zkn_poseidon_fe_t *zkn_poseidon_opt_table(const uint32_t *n,
                                               unsigned nb_inputs,
                                               unsigned *sparse_rounds)
{
#if ZKN_POSEIDON_ARITIES
    if (memcmp(n, POSEIDON_BN254_MODULUS, sizeof(POSEIDON_BN254_MODULUS)) == 0) {
        switch (nb_inputs) {
#if ((ZKN_POSEIDON_ARITIES) >> 1) & 1u
        case 1: *sparse_rounds = 0; return POSEIDON_BN254_T2;
#endif
#if ((ZKN_POSEIDON_ARITIES) >> 2) & 1u
        case 2: *sparse_rounds = 0; return POSEIDON_BN254_T3;
#endif
#if ((ZKN_POSEIDON_ARITIES) >> 3) & 1u
        case 3: *sparse_rounds = 0; return POSEIDON_BN254_T4;
#endif
#if ((ZKN_POSEIDON_ARITIES) >> 4) & 1u
        case 4: *sparse_rounds = 0; return POSEIDON_BN254_T5;
#endif
#if ((ZKN_POSEIDON_ARITIES) >> 5) & 1u
        case 5: *sparse_rounds = 0; return POSEIDON_BN254_T6;
#endif
#if ((ZKN_POSEIDON_ARITIES) >> 6) & 1u
        case 6: *sparse_rounds = 0; return POSEIDON_BN254_T7;
#endif
#if ((ZKN_POSEIDON_ARITIES) >> 7) & 1u
        case 7: *sparse_rounds = 0; return POSEIDON_BN254_T8;
#endif
        default: return NULL;
        }
    }
#endif
#if ZKN_POSEIDON_BLS12381_ARITIES
    if (memcmp(n, POSEIDON_BLS12381_MODULUS, sizeof(POSEIDON_BLS12381_MODULUS)) == 0) {
        switch (nb_inputs) {
#if ((ZKN_POSEIDON_BLS12381_ARITIES) >> 5) & 1u
        case 5: *sparse_rounds = 0; return POSEIDON_BLS12381_T6;
#endif
        default: return NULL;
        }
    }
#endif
    (void)n;
    (void)nb_inputs;
    (void)sparse_rounds;
    return NULL;
}

